// Scene SDF
float sdf(vec3 p){
    vec3 q = p;

    vec3 bp = sdfRepeat(q, vec3(3.,1.,3.));
    vec3 sp = sdfRepeat(q, vec3(3.,1.,3.));

    bp.xz *= rot(sin(p.y) * 0.5);
    float b1 = sdfBox(bp, vec3(0.5,0.5,0.5));
    float b2 = sdfBox(bp, vec3(0.4,0.6,0.4));
    float b3 = sdfBox(bp, vec3(0.4,0.4,0.6));
    float b4 = sdfBox(bp, vec3(0.6,0.4,0.4));

    b1 = abs(b1) - 0.01;
    float b = sdfDifference(b2,b1);

    b = abs(b) - 0.01;
    b = sdfDifference(b3,b);

    b = abs(b) - 0.02;
    b = sdfDifference(b4,b);

    sp.yz *= rot(iTime * 0.5);

    float s = sdfSphere(sp, vec3(0,0,0), 0.2);
    s *= 0.3;

    vec3 dp = sp;
    dp += 
        cos(sp.x * 30.) *
        sin(sp.y * 10.) *
        cos(sp.z * 30.);

    dp *= 3.0;
    dp.yz *= rot(iTime * 0.5);
    float d = sdfSphere(dp, vec3(0,0,0), 0.2);

    s = mix(s,d,0.003);
    s *= 0.6;

    return min(b,s);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    vec3 origin = vec3(iTime * 0.3,iTime * 0.3,-2);
    vec3 dir = normalize(vec3(uv,1.0));

    dir.xz *= rot(iTime * 0.01);

    vec3 col = vec3(0);

    float t = 0.0;

    for (int i=0; i < RM_STEPS; i++){
        vec3 p = origin + dir * t;

        float d = sdf(p);

        t += d;

        col = vec3(i) / float(RM_STEPS);

        if (d < RM_BREAK_NEAR) break;
        if (t > RM_BREAK_FAR) break;
    }

    col.gb += (t * 0.02);

    fragColor = vec4(col,1.);
}

// Raymarching params
#define RM_STEPS 100
#define RM_BREAK_NEAR .0001
#define RM_BREAK_FAR 40.

// 2D rotation
mat2 rot(float r){
    float i = sin(r);
    float j = cos(r);

    return  mat2(j, -i, i, j);
}

// Blending
float sdfIntersect(float a, float b){ return max(a,b); }
float sdfUnion(float a, float b){ return min(a,b); }
float sdfDifference(float a, float b){ return max(-a,b); }

// Ops
vec3 sdfRepeat(vec3 p, vec3 s){
    vec3 q = p - s*round(p/s);
    return q;
}

// Sphere SDF
float sdfSphere(vec3 p, vec3 s, float radius){ return length(p - s) - radius; }

// Box SDF
float sdfBox(vec3 p, vec3 s){
  vec3 q = abs(p) - s;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}
